<script setup>
import { computed, onMounted, ref, watch, nextTick, onBeforeUnmount, defineAsyncComponent } from 'vue'
import Icon from './Icon.vue'
import ClassProfileHeader from './commerce/ClassProfileHeader.vue'
import Art from './Art.vue'
import InsightsDashboard from './InsightsDashboard.vue'
import Community from './Community.vue'
import Competition from './Competition.vue'
import MarketingStudio from './MarketingStudio.vue'
import './expansion.css'
import ProductTour from './ProductTour.vue'
import GettingStarted from './GettingStarted.vue'
import HelpTip from './HelpTip.vue'
import Discover from './Discover.vue'
import QuizStudio from './QuizStudio.vue'
const Operations=defineAsyncComponent(()=>import('./native/Operations.vue'))
const Papers=defineAsyncComponent(()=>import('./native/Papers.vue'))
import LessonQuiz from './LessonQuiz.vue'
import StudentHome from './StudentHome.vue'
import PlatformDashboard from './PlatformDashboard.vue'
import TeachingSpaces from './TeachingSpaces.vue'
import LiveStudio from './LiveStudio.vue'
import AcademicResults from './AcademicResults.vue'
import VideoCourses from './VideoCourses.vue'
const ClassFees=defineAsyncComponent(()=>import('./commerce/ClassFees.vue'))
const Wallet=defineAsyncComponent(()=>import('./commerce/Wallet.vue'))
const FollowUpdates=defineAsyncComponent(()=>import('./commerce/FollowUpdates.vue'))
const Connections=defineAsyncComponent(()=>import('./commerce/Connections.vue'))
const StudySpace=defineAsyncComponent(()=>import('./study/StudySpace.vue'))
const Signup=defineAsyncComponent(()=>import('./native/RegistrationFlow.vue'))
const publishingOptions=ref([])
const featureCatalog=[]
const readConfig=()=>({})
const effectiveFeature=()=>({value:true})
import {readTools,dueTasks,toolActive} from './study/tools'
import SoulCompanion from './SoulCompanion.vue'
const ProviderHome=defineAsyncComponent(()=>import('./native/ProviderHome.vue'))
const Programmes=defineAsyncComponent(()=>import('./native/Programmes.vue'))
const ProfileEditor=defineAsyncComponent(()=>import('./commerce/ProfileEditor.vue'))
import AccountControls from './AccountControls.vue'
import LocalePicker from './LocalePicker.vue'
import StudentAppearance from './StudentAppearance.vue'
import ContactSettings from './ContactSettings.vue'
import MaterialUpload from './materials/MaterialUpload.vue'
const MaterialViewer=defineAsyncComponent(()=>import('./materials/MaterialViewer.vue'))
import {readAppearance,palettes,saveAppearance} from './study/appearance'
import './student-theme.css'
import {isRtl} from './locales'
import { call, isDemo, switchRole, uploadImage, resetDemo } from './service'
import { dayKey, remaining, lkr, graphemes, safeLink, billing } from './rules'
import { labels } from './i18n'

const page = ref('dashboard'), lang = ref(localStorage.getItem('sisu-language') || 'en'), mobile = ref(false)
const t = computed(() => ({...labels.en,...(labels[lang.value]||labels[lang.value.split('-')[0]]||{})}))
const boot = ref(null), rooms = ref([]), sessions = ref([]), news = ref([]), invoices = ref([]), notices = ref([]), members = ref([])
const loading = ref(true), error = ref(''), toast = ref(''), query = ref(''), role = ref('Student'), modal = ref(null), form = ref({}), busy = ref(false)
const detailPage=ref(0),schedulePage=ref(0),detailEnd=ref(false),scheduleEnd=ref(false)
const selected = ref(null), detailTab = ref('Sessions'), enrollments = ref([]), billingData = ref(null), newsIndex = ref({}), filter = ref('All'), paymentFilter = ref('All')
const calendarOffset = ref(0), pickedDate = ref(dayKey()), comment = ref(''), activeVideo = ref(''), billCount = ref(528)
const locationOrigin=location.origin
const paymentProvider=computed(()=>boot.value?.payment_provider==='payhere'?'PayHere':'payments.lk')
const stats = ref({}), insightsData=ref(null), persona=ref(''), invoicePage=ref(0)
const tourOpen=ref(false), marketplaceData=ref(null),marketplaceSelected=ref(''),marketplaceProvider=ref('')
const pageLabels={programmes:'Programmes',team:'Teaching team',profile:'My profile',operations:'Campus desk',papers:'Papers',apps:'Study Room',wallet:'Wallet & payouts',connections:'Profiles & connections',news:'Keep Me Update',payments:'Class fees',control:'Control room',hub:'Learning & teaching',plans:'Plans & billing',signup:'Welcome',study:'Study Room',videos:'Video courses',results:'Results & GPA',live:'Live studio',quizzes:'Lesson quizzes',discover:'Discover',setup:'Education workspace',guide:'Getting started',marketing:'Marketing studio',teachers:'Teachers',competition:'Monthly challenge',people:'Community'}
const appearance=ref({mode:'cozy',accent:'lavender',configured:false})
const studentAccent=computed(()=>{const p=palettes.find(p=>p.id===appearance.value.accent)||palettes[0];return appearance.value.mode==='dark'?p.dark:p.color})
function toggleAppearance(){saveAppearance(boot.value.member.name,{...appearance.value,mode:appearance.value.mode==='dark'?'cozy':'dark'})}
function loadAppearance(){if(boot.value?.member?.name)appearance.value=readAppearance(boot.value.member.name,isDemo)}
watch(()=>boot.value?.member?.name,loadAppearance)
onMounted(()=>window.addEventListener('sisu-appearance',loadAppearance))
onBeforeUnmount(()=>window.removeEventListener('sisu-appearance',loadAppearance))
const teacherOptions = ref([]), listPages=ref({classrooms:0,people:0,payments:0,news:0,notifications:0}), noMore=ref({})
const manager = computed(() => boot.value?.member.role !== 'Student')
const admin = computed(() => boot.value?.member.role === 'Admin')
const launchConfig=ref(readConfig()),personalTools=ref(readTools(''))
function updateLaunch(){launchConfig.value=readConfig()}
function updateTools(){personalTools.value=readTools(boot.value?.member.name||'')}
const datedTasks=date=>isDemo&&role.value==='Student'&&toolActive(personalTools.value,'todo')?dueTasks(personalTools.value,date):[]
const enabled=key=>!isDemo||!featureCatalog.some(f=>f.key===key)||effectiveFeature(key,launchConfig.value).value
onMounted(()=>{window.addEventListener('sisu-config',updateLaunch);window.addEventListener('sisu-tools',updateTools)})
onBeforeUnmount(()=>{window.removeEventListener('sisu-config',updateLaunch);window.removeEventListener('sisu-tools',updateTools)})
watch(()=>boot.value?.member.name,updateTools)
const pageFeature=computed(()=>({discover:'marketplace',competition:'rewards'}[page.value]||page.value))
const blockedPage=computed(()=>isDemo&&!enabled(pageFeature.value))
const nav=computed(()=>[
 {id:'dashboard',icon:'LayoutDashboard'},{id:'classrooms',icon:'BookOpen'},{id:'programmes',icon:'GraduationCap'},{id:'schedule',icon:'CalendarDays'},
 ...(role.value==='Admin'?[{id:'team',icon:'Users'}]:[{id:'hub',icon:'NotebookPen'}]),
 ...(role.value==='Student'?[{id:'study',icon:'Coffee'}]:[{id:'wallet',icon:'Wallet'}]),
 {id:'connections',icon:'Search'},{id:'payments',icon:'CreditCard'},{id:'news',icon:'Newspaper'},{id:'profile',icon:'IdCard'}
])
const hubItems=computed(()=>[{id:'videos',icon:'Clapperboard',label:'Video courses',description:'Your lessons, at your own pace.'},{id:'papers',icon:'ClipboardCheck',label:'Papers',description:'Manual papers, premium AI drafts and marking.'},{id:'results',icon:'GraduationCap',label:'Results & GPA',description:'Published results and your next milestone.'},{id:'operations',icon:'ListChecks',label:'Attendance & support',description:'Class registers and your support conversations.'},{id:'learning',icon:'NotebookPen',label:'Assignments & certificates',description:'Your connected Frappe Learning tools.'},{id:'competition',icon:'Award',label:'Monthly challenge',description:'Celebrate steady learning.'},...(manager.value?[{id:'live',icon:'Youtube',label:'Live studio',description:'Manage your live lessons.'},{id:'setup',icon:'IdCard',label:'Your education profile',description:'Branding, affiliations and identity.'}]:[])].filter(n=>(isDemo||['learning','live','papers','operations'].includes(n.id))&&enabled(n.id)))
async function enterSignup(roleName){role.value=roleName;await changeRole()}

const filteredRooms = computed(() => rooms.value.filter(r => (!query.value || `${r.title} ${r.subject} ${r.teacher_name}`.toLowerCase().includes(query.value.toLowerCase())) && (filter.value === 'All' || (filter.value === 'Unlocked' ? r.access.allowed : !r.access.allowed))))
const todaySessions = computed(() => sessions.value.filter(s => s.starts_at.slice(0,10) === dayKey() && s.status !== 'Cancelled').sort((a,b)=>a.starts_at.localeCompare(b.starts_at)))
const unpaid = computed(() => invoices.value.filter(i => i.status !== 'Paid'))
const filteredInvoices = computed(() => invoices.value.filter(i => paymentFilter.value === 'All' || i.status === paymentFilter.value))
const visibleInvoices=computed(()=>isDemo?filteredInvoices.value.slice(invoicePage.value*25,invoicePage.value*25+25):filteredInvoices.value)
watch(paymentFilter,()=>invoicePage.value=0)
const monthDate = computed(() => { const d = new Date(dayKey()+'T12:00:00'); d.setDate(1); d.setMonth(d.getMonth()+calendarOffset.value); return d })
const monthLabel = computed(() => monthDate.value.toLocaleDateString(lang.value,{month:'long',year:'numeric'}))
const calendar = computed(() => { const d=new Date(monthDate.value); d.setDate(1-((d.getDay()+6)%7)); const last=new Date(monthDate.value.getFullYear(),monthDate.value.getMonth()+1,0).getDate();const count=Math.ceil((((monthDate.value.getDay()+6)%7)+last)/7)*7; return Array.from({length:count},(_,i)=>{const x=new Date(d);x.setDate(d.getDate()+i);return {key:dayKey(x),day:x.getDate(),muted:x.getMonth()!==monthDate.value.getMonth()} }) })
const selectedSessions = computed(() => sessions.value.filter(s=>s.starts_at.slice(0,10)===pickedDate.value).sort((a,b)=>a.starts_at.localeCompare(b.starts_at)))
const fullDate = new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',timeZone:'Asia/Colombo'}).format(new Date())
function roomName(name){return rooms.value.find(r=>r.name===name)?.subject || name}
function time(value){return value?.slice(11,16) || ''}
function dateLabel(value){return value ? new Date(value.slice(0,10)+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'}) : ''}
function notify(message){toast.value=message; setTimeout(()=>toast.value='',5500)}
function openMarketClass(name){marketplaceSelected.value=name;navigate('discover')}
function navigate(value){if(value==='discover'||value==='teachers'||value==='setup')value='connections';if(value==='quizzes')value='papers';if(value==='plans'||value==='apps')value='study';page.value=value;mobile.value=false;query.value='';filter.value='All';history.replaceState(null,'','#'+value)}
async function refresh(){
  error.value=''
  try {
    boot.value=await call('bootstrap');role.value=boot.value.member.role;persona.value=boot.value.member.name;stats.value=await call('dashboard_summary');if(isDemo){insightsData.value=await call('insights');marketplaceData.value=await call('marketplace')}
    const results=await Promise.all([call('classrooms'),call('schedule',{starts_on:calendar.value[0].key,ends_on:calendar.value.at(-1).key}),call('news'),call('invoices'),call('notifications')])
    ;[rooms.value,sessions.value,news.value,invoices.value,notices.value]=results
    if(admin.value){members.value=await call('members');billingData.value=null}
    else if(manager.value) members.value=isDemo?await call('members'):[boot.value.member]
    if(manager.value){teacherOptions.value=await call('teachers');publishingOptions.value=await call('publishing_options',{},'catalog')}
    listPages.value={classrooms:0,people:0,payments:0,news:0,notifications:0};noMore.value={}
    if(selected.value) selected.value=await call('classroom_detail',{name:selected.value.room.name})
  }catch(e){error.value=e.message}finally{loading.value=false}
}
async function changePersona(){switchRole(role.value,persona.value);selected.value=null;invoicePage.value=0;await refresh()}
async function changeRole(){tourOpen.value=false;invoicePage.value=0;switchRole(role.value);selected.value=null;navigate('dashboard');await refresh()}
async function openRoom(room){try{selected.value=await call('classroom_detail',{name:room.name});detailTab.value='Sessions';activeVideo.value='';detailPage.value=0;detailEnd.value=false; if(manager.value) enrollments.value=await call('enrollments',{classroom:room.name});openDialog('room')}catch(e){notify(e.message)}}
const deletedRooms=ref([]),deletedPage=ref(0),deleteName=ref('')
async function showDeleted(pageNumber=0){busy.value=true;error.value='';try{deletedRooms.value=await call('classrooms',{deleted:1,page:pageNumber});deletedPage.value=pageNumber;openDialog('deleted-classrooms')}catch(e){notify(e.message)}finally{busy.value=false}}
function confirmDelete(){error.value='';deleteName.value='';openDialog('delete-classroom')}
async function removeClassroom(){if(deleteName.value!==selected.value?.room.title)return;busy.value=true;error.value='';try{await call('set_classroom_deleted',{name:selected.value.room.name,deleted:1});selected.value=null;closeDialog();await refresh();notify('Classroom deleted. You can restore it from Deleted classrooms.')}catch(e){error.value=e.message}finally{busy.value=false}}
async function leaveAssignment(){try{await call('leave_class',{classroom:selected.value.room.name},'teaching');closeDialog();await refresh();notify('You have left this class. Your personal classrooms are unchanged.')}catch(e){notify(e.message)}}
async function restoreClassroom(room){busy.value=true;error.value='';try{await call('set_classroom_deleted',{name:room.name,deleted:0});selected.value=null;await refresh();await showDeleted(deletedPage.value);notify('Classroom restored. Its saved schedule and access rules apply again.')}catch(e){error.value=e.message}finally{busy.value=false}}
let lastFocus
async function openDialog(type){lastFocus=document.activeElement;modal.value=type;await nextTick();document.querySelector('.modal input, .modal textarea, .modal button')?.focus()}
function closeDialog(){modal.value=null;activeVideo.value='';lastFocus?.focus()}
function trapFocus(event){if(event.key==='Escape'){closeDialog();return}if(event.key!=='Tab')return;const items=[...event.currentTarget.querySelectorAll('button,a[href],input,select,textarea')].filter(el=>!el.disabled&&el.offsetParent!==null);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){last.focus();event.preventDefault()}else if(!event.shiftKey&&document.activeElement===last){first.focus();event.preventDefault()}}
function edit(type, room=null, item=null){
  const today=dayKey();const defaultRoom=room?.name || rooms.value[0]?.name
  form.value = type==='classroom' ? {title:'',subject:'',billing_type:'Monthly',teacher_access:'Teaching only',teacher:manager.value&&!admin.value?boot.value.member.name:teacherOptions.value[0]?.name,description:'',fee:0,font:'sans',motivation:'',comments_enabled:1,published:0,public_provider:'',fee_mode:'Paid',schedule_label:'',exam_date:'',allow_teacher_access_override:0,...(room||{})}
    :type==='session'? {classroom:defaultRoom,title:'',starts_at:today+'T16:00',ends_at:today+'T18:00',mode:'Online',status:'Scheduled',comments:'Inherit',location:'',description:'',youtube_id:'',meeting_provider:'YouTube',meeting_url:'',...(item||{})}
    :type==='news'?{headline:'',description:'',cta_label:'',cta_url:'',starts_on:today,ends_on:today,images:[]}
    :type==='member'?{full_name:'',user:'',role:'Teacher',phone:'',language:'en',category:'O/L',medium:'Sinhala',grade:'11',school:'',guardian:'',district:'Colombo',stream:'General'}
    :type==='material'?{classroom:defaultRoom,title:'',kind:'Document',url:'',description:'',file_id:'',preview_file_id:'',download_policy:'View only'}
    :type==='announcement'?{classroom:defaultRoom,headline:'',body:''}
    :type==='enroll'?{classroom:defaultRoom,student:members.value.find(m=>m.role==='Student')?.name,installments:[{amount:room?.fee||0,due_date:today}]}
    :type==='access'?{enrollment:item.name,override:item.access_override,grace_until:item.grace_until,reason:''}
    :type==='payment'?{invoice:item.name,first_name:boot.value.member.full_name.split(' ')[0],last_name:boot.value.member.full_name.split(' ').slice(1).join(' '),phone:boot.value.member.phone||'',address:'',city:''}
    :{...boot.value.institute}
  openDialog(type)
}
async function submit(){
  busy.value=true;error.value=''
  try{
    if(modal.value==='material'&&form.value.kind==='Document'&&!form.value.file_id)throw Error('Upload a document, or choose Link for an external resource')
    if(form.value.motivation && graphemes(form.value.motivation)>30) throw Error('Keep the motivation line within 30 characters')
    if(modal.value==='news' && (graphemes(form.value.headline)>80 || graphemes(form.value.description)>240))throw Error('Headline: 80 characters. Description: 240 characters.')
    const methods={classroom:'save_classroom',session:'save_session',material:'add_material',announcement:'post_announcement',news:'publish_news',member:'add_member',enroll:'enroll',branding:'save_branding'}
    if(modal.value==='access') await call('set_access',form.value)
    else if(modal.value==='payment'){
      const result=await call('checkout',{invoice:form.value.invoice,customer:form.value},'payments')
      if(result.redirect_url){const target=new URL(result.redirect_url);if(target.protocol!=='https:'||target.hostname!=='payments.lk')throw Error('Invalid payment destination');location.assign(target.href);return}
      const el=document.createElement('form');el.method='POST';el.action=result.action
      Object.entries(result.fields).forEach(([name,value])=>{const input=document.createElement('input');input.type='hidden';input.name=name;input.value=value;el.append(input)});document.body.append(el);el.submit();return
    }else await call(methods[modal.value],{data:form.value})
    closeDialog();await refresh();notify('Saved. Your learning space is up to date.')
  }catch(e){error.value=e.message}finally{busy.value=false}
}
async function upload(event,field){try{for(const file of event.target.files){const url=await uploadImage(file);if(field==='images'){if(form.value.images.length>=5)throw Error('Maximum 5 images');form.value.images.push({image:url,alt:form.value.headline||file.name})}else form.value[field]=url}}catch(e){error.value=e.message}}
async function sendComment(){try{if(!comment.value.trim())return;await call('post_feedback',{session:form.value.feedback_session,body:comment.value});comment.value='';selected.value=await call('classroom_detail',{name:selected.value.room.name});notify('Your feedback has been posted.')}catch(e){notify(e.message)}}
async function demoPay(){await call('demo_payment',{invoice:form.value.invoice});closeDialog();await refresh();notify('Demo payment recorded. No money was collected.')}
function receipt(invoice){const text=`${isDemo?'DEMO — NOT A PAYMENT RECEIPT\n':''}${boot.value.institute.title}\nReceipt: ${invoice.receipt_number}\nStudent: ${invoice.student}\nInvoice: ${invoice.name}\nClassroom: ${roomName(invoice.classroom)}\nAmount: ${lkr(invoice.amount)}\nPaid: ${invoice.paid_at||'Recorded'}\n`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download=`receipt-${invoice.name}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function youtube(action,session,status){try{const result=await call(action,session?{session:session.name,...(status?{status}:{})}:{},'youtube');if(typeof result==='string')location.href=result;else{notify(action==='schedule_broadcast'?'YouTube broadcast scheduled. Finish encoder setup in YouTube Studio.':'YouTube broadcast updated.');await refresh()}}catch(e){notify(e.message)}}
async function savePreferences(event){const values=new FormData(event.target);try{await call('notification_preferences',{phone:values.get('phone'),opted_in:values.get('opted_in')?1:0,language:lang.value});notify('Notification preferences saved.')}catch(e){notify(e.message)}}
function exportReport(){const rows=[['Invoice','Student','Classroom','Amount LKR','Due','Status'],...invoices.value.map(i=>[i.name,i.student,roomName(i.classroom),i.amount,i.due_date,i.status])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));a.download='payment-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function toggleMember(member){try{await call('set_member_active',{member_id:member.name,active:member.active?0:1});await refresh();notify('Membership updated.')}catch(e){notify(e.message)}}
async function loadMore(){
  const config={classrooms:['classrooms',rooms,24],people:['members',members,50],payments:['invoices',invoices,50],news:['news',news,24],notifications:['notifications',notices,50]}[page.value]
  if(!config)return
  try{const next=listPages.value[page.value]+1;const result=await call(config[0],{page:next,...(page.value==='classrooms'?{search:query.value}:{})});config[1].value.push(...result);listPages.value[page.value]=next;noMore.value[page.value]=result.length<config[2]}catch(e){notify(e.message)}
}
let searchTimer
watch(query,value=>{if(page.value!=='classrooms')return;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{try{rooms.value=await call('classrooms',{search:value});listPages.value.classrooms=0;noMore.value.classrooms=false}catch(e){notify(e.message)}},250)})
async function moreDetail(){try{const result=await call('classroom_detail',{name:selected.value.room.name,page:detailPage.value+1});if(!result.access.allowed){selected.value=result;return}for(const key of ['sessions','materials','feedback','announcements'])selected.value[key].push(...result[key]);detailEnd.value=['sessions','materials','feedback','announcements'].every(k=>result[k].length<50);detailPage.value++}catch(e){notify(e.message)}}
async function moreSchedule(){try{const result=await call('schedule',{page:schedulePage.value+1,starts_on:calendar.value[0].key,ends_on:calendar.value.at(-1).key});sessions.value.push(...result);schedulePage.value++;scheduleEnd.value=result.length<50}catch(e){notify(e.message)}}
async function updateSchedule(){schedulePage.value=0;scheduleEnd.value=false;if(!boot.value)return;try{sessions.value=await call('schedule',{starts_on:calendar.value[0].key,ends_on:calendar.value.at(-1).key})}catch(e){notify(e.message)}}
watch(calendarOffset,updateSchedule)
function changeNews(item,delta){newsIndex.value[item.name]=((newsIndex.value[item.name]||0)+delta+item.images.length)%item.images.length}
watch(lang,value=>{document.documentElement.lang=value;document.documentElement.dir=isRtl(value)?'rtl':'ltr';localStorage.setItem('sisu-language',value)},{immediate:true})
watch(page,()=>{error.value=''})
watch(activeVideo,async value=>{if(value){await nextTick();document.querySelector('.video-frame')?.scrollIntoView({behavior:'smooth',block:'center'})}})
watch(modal,value=>{document.body.style.overflow=value?'hidden':''})
onMounted(()=>{const hash=location.hash.slice(1);if(['dashboard','classrooms','schedule','learning','payments','news','people','settings','notifications','marketing','competition','teachers','guide','discover','setup','quizzes','live','results','videos','study','plans','signup','control','hub','apps','wallet','connections','papers','operations','programmes','team','profile'].includes(hash))navigate(hash);refresh()})
</script>

<template>
  <Signup v-if="page==='signup'" @back="navigate('dashboard')" @dashboard="enterSignup"/>
  <div v-else-if="loading" class="loading-screen"><div class="brand-symbol">s</div><p>Making room for learning…</p></div>
  <div v-else-if="!boot" class="login-screen"><div class="login-card"><div class="wordmark"><span class="brand-symbol">s</span>sisu<span class="brand-dot">.</span></div><h1>Your next chapter<br>starts here.</h1><p>Sign in to your institute’s learning space.</p><p v-if="error" class="error" role="alert">{{error}}</p><a class="button primary" href="/login?redirect-to=/campus">Sign in with your institute account <Icon name="ArrowRight"/></a><button class="button subtle" @click="navigate('signup')">Create an account</button><small>Students · Teachers · Administrators</small></div><Art/></div>
  <div v-else class="app-shell" :data-student-theme="appearance.mode" :style="{'--brand':boot.institute.accent||'#7563e6','--student-accent':studentAccent}">
    <a href="#main-content" class="skip-link">Skip to main content</a><button v-if="mobile" class="sidebar-overlay" aria-label="Close navigation" @click="mobile=false"></button>
    <aside class="sidebar" :class="{expanded:mobile}">
      <a href="#dashboard" class="wordmark" @click.prevent="navigate('dashboard')"><span class="brand-symbol">s</span>sisu<span class="brand-dot">.</span></a>
      <div class="institute-switch"><img v-if="boot.institute.logo" :src="boot.institute.logo" alt="Institute logo"><span v-else class="institute-monogram">{{boot.institute.code.slice(0,2)}}</span><div><strong>{{boot.institute.title}}</strong><small>Your institute · {{boot.institute.code}}</small></div><Icon name="ChevronsUpDown" :size="14"/></div>
      <p class="nav-label">{{t.workspace}}</p>
      <nav aria-label="Main navigation"><button v-for="item in nav" :key="item.id" :aria-current="page===item.id?'page':undefined" :class="{active:page===item.id}" @click="navigate(item.id)"><Icon :name="item.icon"/><span>{{lang!=='en'&&lang!=='en-US'?t[item.id]:(pageLabels[item.id]||t[item.id])}}</span><span v-if="item.id==='payments' && unpaid.length" class="nav-count">{{unpaid.length}}</span><i v-if="item.id==='news'" class="nav-dot"></i></button></nav>
      <div class="sidebar-bottom"><div class="help-card"><div class="help-icon"><Icon name="Sprout" :size="27"/></div><strong>{{t.help}}</strong><p>{{t.helpBody}}</p><button @click="openDialog('support')">{{t.support}} <Icon name="ArrowUpRight" :size="14"/></button></div><button class="settings-nav" :class="{active:page==='settings'}" @click="navigate('settings')"><Icon name="Settings2"/>{{t.settings}}</button><div class="sidebar-foot"><span class="tiny-logo">✳</span> A brighter way to learn.</div></div>
    </aside>
    <div class="workspace">
      <header class="topbar"><button class="icon-button mobile-menu" aria-label="Open menu" @click="mobile=true"><Icon name="Menu"/></button><div class="breadcrumb">Your campus <Icon name="ChevronRight" :size="13"/><strong>{{lang!=='en'&&lang!=='en-US'?t[page]:(pageLabels[page]||t[page])}}</strong></div><div class="top-actions"><button v-if="isDemo" class="button subtle small signup-preview-button" @click="navigate('signup')">Sign up / sign in</button><button class="icon-button appearance-toggle" @click="toggleAppearance" :aria-label="appearance.mode==='dark'?'Switch to light mode':'Switch to dark mode'" :title="appearance.mode==='dark'?'Light mode':'Dark mode'"><Icon :name="appearance.mode==='dark'?'Sun':'Moon'" :size="19"/></button><button class="tour-trigger button subtle small" @click="tourOpen=true"><Icon name="Play" :size="15"/>Product tour</button><LocalePicker v-model="lang"/><button class="icon-button notification-button" aria-label="Notifications" @click="navigate('notifications')"><Icon name="Bell"/><i v-if="notices.length"></i></button><span class="top-divider"></span><button class="profile-button" @click="navigate('profile')"><span class="avatar">{{boot.member.full_name.slice(0,1)}}</span><div><strong>{{boot.member.full_name.split(' ')[0]}}</strong><small>{{boot.member.role==='Admin'?'Institute Admin':boot.member.role==='PlatformAdmin'?'Platform Owner':boot.member.role}}</small></div><Icon name="ChevronDown" :size="14"/></button></div></header>
      <div v-if="isDemo" class="preview-bar"><span><span class="preview-dot"></span> Interactive preview <span class="preview-extra">· Sample data saved in this browser. No live payments or messages.</span></span><div><label>View as <select v-model="role" @change="changeRole"><option>Student</option><option>Teacher</option><option value="Admin">Institute Admin</option><option value="PlatformAdmin">Platform Owner</option></select></label><select v-if="boot.personas?.length>1" v-model="persona" @change="changePersona" aria-label="Demo account" class="preview-persona"><option v-for="p in boot.personas" :key="p.name" :value="p.name">{{p.full_name}}{{p.category?' · '+p.category:''}}</option></select></div></div>
      <main id="main-content"><div v-if="['videos','quizzes','results','learning','competition','live','setup'].includes(page)" class="hub-subnav"><button class="text-button" @click="navigate('hub')"><Icon name="ChevronLeft" :size="15"/> Learning & teaching</button></div><div v-if="page==='dashboard'&&boot.member.role==='Student'&&!appearance.configured" class="profile-cozy-prompt"><Icon name="Palette"/><div><strong>Make this little corner yours.</strong><p>Choose your cozy profile colors, verify your email and choose your class updates.</p></div><button class="button subtle small" @click="navigate('settings')">Set up my profile</button></div>
        <div v-if="error&&!modal" class="error" role="alert">{{error}} <button @click="refresh">Retry</button></div>
        <section v-if="blockedPage" class="panel" style="padding:36px"><span class="badge peach">{{featureCatalog.find(f=>f.key===pageFeature)?.comingSoon?'Coming soon':'Not enabled'}}</span><h2>A little further down the road.</h2><p>This capability is not available in the current workspace configuration.</p><button class="button subtle" @click="navigate('hub')">Back to learning</button></section>
        <ClassFees v-else-if="page==='payments'&&role==='Student'" :invoices="invoices" :rooms="rooms" :marketplace="marketplaceData" @pay="edit('payment',null,$event)" @receipt="receipt" @refresh="refresh" @notify="notify"/>
        <Wallet v-else-if="page==='wallet'&&role!=='Student'" :key="persona" :member="boot.member" @notify="notify"/><Connections v-else-if="page==='connections'" :key="persona" :member="boot.member" :marketplace="marketplaceData" @navigate="navigate" @notify="notify"/>
        <AcademicResults v-else-if="isDemo&&page==='results'" :key="persona" :rooms="rooms" :member="boot.member" :institute="boot.institute" @notify="notify"/>
        <LiveStudio v-else-if="manager&&page==='live'" :key="persona" :sessions="sessions" :rooms="rooms" :member="boot.member" @refresh="refresh" @notify="notify"/>
        <PlatformDashboard v-else-if="isDemo&&role==='PlatformAdmin'&&page==='dashboard'"/>
        <Operations v-else-if="page==='operations'" :member="boot.member" :rooms="rooms" :sessions="sessions"/><Papers v-else-if="page==='papers'" :member="boot.member" :rooms="rooms"/><QuizStudio v-else-if="isDemo&&page==='quizzes'" :key="persona" :rooms="rooms" :member="boot.member" @notify="notify"/>
        <Discover v-else-if="isDemo&&page==='discover'&&marketplaceData" :data="marketplaceData" :member="boot.member" :initial-class="marketplaceSelected" :initial-provider="marketplaceProvider" @opened="marketplaceSelected='';marketplaceProvider=''" @refresh="refresh" @notify="notify" @setup="navigate('setup')"/>
        <Connections v-else-if="page==='setup'" :member="boot.member" :marketplace="marketplaceData" @notify="notify" @navigate="navigate"/>
        <GettingStarted v-else-if="page==='guide'" :role="role" :demo="isDemo" @tour="tourOpen=true" @navigate="navigate"/>
        <template v-else-if="isDemo&&manager&&page==='dashboard'&&insightsData"><TeachingSpaces v-if="role==='Teacher'&&marketplaceData" :key="persona" :member="boot.member" :institute="boot.institute" :rooms="rooms" :marketplace="marketplaceData" @room="openRoom" @profile="marketplaceProvider=$event;navigate('discover')" @setup="navigate('setup')"/><InsightsDashboard :data="insightsData" :member="boot.member" @navigate="navigate" @room="openRoom" @create="edit" @video="openDialog('video')"/></template>
        <StudentHome v-else-if="isDemo&&role==='Student'&&page==='dashboard'&&insightsData&&marketplaceData" :data="insightsData" :marketplace="marketplaceData" :rooms="rooms" :sessions="sessions" :invoices="invoices" :member="boot.member" :institute="boot.institute" @navigate="navigate" @room="openRoom" @marketclass="openMarketClass" @video="openDialog('video')"/>
        <ProviderHome v-else-if="(page==='dashboard'&&manager)||page==='team'" :member="boot.member" :institute="boot.institute" :team-only="page==='team'" @navigate="navigate" @create="edit('classroom')" @room="openRoom"/>
        <Programmes v-else-if="page==='programmes'" :member="boot.member" :rooms="rooms" @refresh="refresh" @room="openRoom" @navigate="navigate"/>
        <ProfileEditor v-else-if="page==='profile'" :member="boot.member" @navigate="navigate" @saved="notify('Your profile changes are saved. Identity changes may require verification.');refresh()"/>
        <template v-else-if="page==='dashboard'">
          <div class="page-heading"><div><div class="eyebrow">YOUR EVERYDAY, A LITTLE BRIGHTER</div><h1>{{t.hello}}, {{boot.member.full_name.split(' ')[0]}} <span class="greeting-spark">✺</span></h1><p>{{t.subtitle}}</p></div><div class="date-chip"><Icon name="CalendarDays" :size="17"/>{{fullDate}}</div></div>
          <button v-if="isDemo" class="video-teaser" @click="openDialog('video')"><span class="video-play"><Icon name="Play" :size="24"/></span><div><span class="eyebrow">YOUR CLASSROOM, WHEREVER YOU ARE</span><h3>Watch your sample classroom video</h3><p>Your YouTube example plays here in the LMS.</p></div><Icon name="ArrowUpRight"/></button><section v-if="isDemo&&insightsData" class="panel student-progress"><div class="section-heading"><h3>Your learning, moving forward</h3><button class="text-button" @click="navigate('competition')">Monthly challenge · #{{insightsData.ownRank?.rank}}</button></div><div v-for="p in insightsData.progress" class="category-meter"><div><strong>{{p.subject}}</strong><span>{{p.completed}} / {{p.total}} lessons · {{p.quiz}}% quiz average</span></div><div class="meter-track"><i :style="{width:p.completed/p.total*100+'%'}"></i></div></div></section>
          <div class="dashboard-columns"><div class="main-column">
            <section class="hero"><div class="hero-copy"><span class="hero-label"><span></span> YOUR SPACE TO GROW</span><h2>{{t.welcome}}</h2><p>You bring the curiosity.<br>We’ll bring your classroom closer.</p><button class="button dark" @click="navigate('classrooms')">{{t.continue}} <Icon name="ArrowRight" :size="17"/></button></div><Art/><div class="hero-caption"><span class="mini-avatar">N</span><span class="mini-avatar second">K</span><span class="mini-avatar third">D</span><span>Good teachers. Great possibilities.</span></div></section>
            <div class="stats-row"><div class="stat-card"><span class="stat-icon violet"><Icon name="BookOpen"/></span><div><strong>{{String(stats.classrooms||0).padStart(2,'0')}}</strong><span>{{manager?'Your classrooms':'Active classrooms'}}</span></div><Icon class="stat-arrow" name="ArrowUpRight" :size="17"/></div><div class="stat-card"><span class="stat-icon peach"><Icon name="CalendarCheck2"/></span><div><strong>{{todaySessions.length.toString().padStart(2,'0')}}</strong><span>Classes today</span></div></div><div class="stat-card"><span class="stat-icon mint"><Icon name="CircleCheck"/></span><div><strong>{{String(stats.paid_count||0).padStart(2,'0')}}</strong><span>Payments settled</span></div></div></div>
            <div class="section-heading"><div><h2>{{t.classrooms}}</h2><p>A familiar space. Something new to learn.</p></div><button class="text-button" @click="navigate('classrooms')">{{t.viewAll}} <Icon name="ArrowRight" :size="15"/></button></div>
            <div class="room-grid dashboard-rooms"><article v-for="(room,index) in rooms.slice(0,3)" :key="room.name" class="room-card"><button class="room-cover" :class="room.color||['violet','peach','mint'][index%3]" @click="openRoom(room)" :aria-label="'Open '+room.title"><img v-if="room.cover_image" :src="room.cover_image" alt="" loading="lazy"><template v-else><span class="subject-art" :class="{atom:index===1}">{{index===0?'ƒ(x)':index===1?'⚛':'H₂O'}}</span><span class="art-orbit"></span><span class="art-star">✧</span><span class="cover-label">{{room.tag||room.subject}}</span></template><span class="cover-status"><Icon :name="room.access.allowed?'ArrowUpRight':'LockKeyhole'" :size="16"/></span></button><div class="room-body"><span class="subject-label">{{room.subject}}</span><button class="room-title" :class="room.font" @click="openRoom(room)">{{room.title}}</button><div class="teacher-line"><img v-if="room.profile_image" :src="room.profile_image" class="teacher-avatar" alt=""><span v-else class="teacher-avatar" :class="room.color">{{room.teacher_name?.slice(0,1)||'T'}}</span>{{room.teacher_name}}</div><div class="room-card-footer"><span :class="['access-label',room.access.allowed?'green':'amber']"><Icon :name="room.access.allowed?'CircleCheck':'LockKeyhole'" :size="12"/>{{room.access.allowed?'Ready to learn':'Payment required'}}</span><button class="arrow-button" @click="openRoom(room)" :aria-label="'Open '+room.title"><Icon name="ArrowRight" :size="17"/></button></div></div></article><div v-if="!rooms.length" class="empty-state"><Icon name="BookOpen"/><h3>A fresh learning space</h3><p>{{manager?'Create your first classroom to get started.':'Your enrolled classrooms will appear here.'}}</p><button v-if="manager" class="button primary" @click="edit('classroom')">Create classroom</button></div></div>
            <section class="campus-strip" v-if="news.length"><div class="strip-icon"><Icon name="Megaphone" :size="23"/></div><div><span class="eyebrow">AROUND YOUR CAMPUS</span><h3>{{news[0].headline}}</h3><p>{{news[0].description}}</p></div><button class="round-button" aria-label="Read campus updates" @click="navigate('news')"><Icon name="ArrowUpRight"/></button></section>
          </div><aside class="right-column">
            <section class="panel calendar-panel"><div class="section-heading"><h3>{{monthLabel}}</h3><div class="inline"><button class="icon-button small" aria-label="Previous month" @click="calendarOffset--"><Icon name="ChevronLeft" :size="16"/></button><button class="icon-button small" aria-label="Next month" @click="calendarOffset++"><Icon name="ChevronRight" :size="16"/></button></div></div><div class="mini-calendar"><span v-for="d in ['M','T','W','T','F','S','S']" class="weekday">{{d}}</span><button v-for="d in calendar" :key="d.key" :class="{muted:d.muted,chosen:d.key===pickedDate,today:d.key===dayKey()}" :aria-label="d.key" @click="pickedDate=d.key;navigate('schedule')">{{d.day}}<i v-if="sessions.some(s=>s.starts_at.startsWith(d.key))"></i></button></div></section>
            <section class="today-section"><div class="section-heading"><h3>{{t.today}}</h3><span class="count-pill">{{todaySessions.length}}</span></div><article v-for="(s,index) in todaySessions" :key="s.name" class="today-card" :class="index%2?'peach':'violet'"><div class="inline spread"><span class="session-mode"><Icon :name="s.mode==='Online'?'Video':'MapPin'" :size="13"/>{{s.mode}} class</span><span class="session-dot"></span></div><h4>{{s.title}}</h4><p>{{roomName(s.classroom)}}</p><div class="session-bottom"><span><Icon name="Clock3" :size="13"/>{{time(s.starts_at)}} – {{time(s.ends_at)}}</span><button class="round-button" :aria-label="'View '+s.title" @click="openRoom(rooms.find(r=>r.name===s.classroom))"><Icon name="ArrowUpRight" :size="18"/></button></div></article><div v-if="!todaySessions.length" class="empty-mini"><Icon name="Coffee"/><p>A little breathing room.<br>No classes today.</p></div><button class="full-link" @click="navigate('schedule')">View your full schedule <Icon name="ArrowRight" :size="15"/></button></section>
            <section class="exam-card" v-if="rooms.find(r=>r.exam_date)"><span class="exam-icon"><Icon name="Hourglass" :size="20"/></span><div class="eyebrow">YOUR NEXT BIG CHAPTER</div><div class="countdown">{{remaining(rooms.find(r=>r.exam_date).exam_date)}}<span>days to go</span></div><p>{{rooms.find(r=>r.exam_date).subject}} · Exam</p><div class="exam-line"></div><strong>{{rooms.find(r=>r.exam_date).motivation||'Make today count.'}}</strong><span class="exam-decoration">✳</span></section>
          </aside></div>
        </template>

        <template v-else-if="page==='classrooms'"><div class="page-heading"><div><div class="eyebrow">A PLACE FOR EVERY POSSIBILITY</div><h1>{{t.classrooms}} <HelpTip text="Classroom access follows enrollment, verified installments, grace periods and authorised manual overrides."/></h1><p>{{t.classTitle}}</p></div><div v-if="manager" class="inline wrap"><button class="button subtle" @click="showDeleted(0)">Deleted classrooms</button><button v-if="manager" class="button primary" @click="edit('classroom')"><Icon name="Plus" :size="17"/>Create classroom</button></div></div><div class="toolbar"><div class="tabs"><button v-for="f in ['All','Unlocked','Locked']" :class="{selected:filter===f}" @click="filter=f">{{f}}</button></div><label class="search"><Icon name="Search" :size="17"/><input v-model="query" :placeholder="t.search" aria-label="Search classrooms"></label></div><div class="room-grid all-rooms"><article v-for="(room,index) in filteredRooms" :key="room.name" class="room-card"><button :aria-label="'Open '+room.title" class="room-cover large" :class="room.color||['violet','peach','mint'][index%3]" @click="openRoom(room)"><img v-if="room.cover_image" :src="room.cover_image" alt="" loading="lazy"><template v-else><span class="subject-art">{{['ƒ(x)','⚛','H₂O'][index%3]}}</span><span class="art-orbit"></span><span class="art-star">✧</span></template></button><div class="room-body"><ClassProfileHeader :room="room" @open="openRoom(room)"/><div class="inline spread"><span class="subject-label">{{room.subject}}</span><span class="badge" :class="room.access.allowed?'green':'amber'">{{room.access.allowed?'Unlocked':'Locked'}}</span></div><div v-if="room.exam_date" class="tiny-countdown"><Icon name="Hourglass" :size="14"/>{{remaining(room.exam_date)}} days to exam</div><div class="room-card-footer"><span>{{room.programme?'Included in programme':lkr(room.fee)+(room.billing_type==='Monthly'?' / month':'')}}</span><button class="text-button" @click="openRoom(room)">{{t.open}} <Icon name="ArrowRight" :size="16"/></button></div></div></article></div><div v-if="!filteredRooms.length" class="empty-state"><Icon name="Search"/><h3>No classrooms found</h3><p>Try another search or filter.</p></div></template>

        <template v-else-if="page==='schedule'"><div class="page-heading"><div><div class="eyebrow">MAKE TIME FOR YOUR FUTURE</div><h1>{{t.schedule}} <HelpTip text="All class times are interpreted in Sri Lanka time (Asia/Colombo, UTC+05:30)."/></h1><p>Your week, a little more organised. All times in Sri Lanka.</p></div><button v-if="manager" class="button primary" @click="edit('session')"><Icon name="Plus" :size="17"/>Schedule a class</button></div><div v-if="!isDemo&&sessions.length>=50&&!scheduleEnd" class="pagination"><button class="button subtle" @click="moreSchedule">Load more scheduled sessions</button></div><div class="schedule-layout"><section class="panel"><div class="section-heading"><h2>{{monthLabel}}</h2><div class="inline"><button class="button subtle" @click="calendarOffset=0;pickedDate=dayKey()">Today</button><button class="icon-button" aria-label="Previous month" @click="calendarOffset--"><Icon name="ChevronLeft"/></button><button class="icon-button" aria-label="Next month" @click="calendarOffset++"><Icon name="ChevronRight"/></button></div></div><div class="full-calendar"><span class="weekday" v-for="d in ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']">{{d}}</span><button v-for="d in calendar" :key="d.key" :class="{muted:d.muted,chosen:d.key===pickedDate,today:d.key===dayKey()}" @click="pickedDate=d.key"><span>{{d.day}}</span><small v-for="task in datedTasks(d.key).slice(0,1)" class="mint">✓ {{task.title}}</small><small v-for="s in sessions.filter(s=>s.starts_at.startsWith(d.key)).slice(0,2)" :class="s.mode==='Physical'?'peach':'violet'">{{time(s.starts_at)}} {{s.title}}</small></button></div></section><aside class="panel day-agenda"><span class="eyebrow">YOUR DAY AT A GLANCE</span><h2>{{dateLabel(pickedDate)}}</h2><article v-for="s in selectedSessions" class="agenda-item"><span class="time-label">{{time(s.starts_at)}} – {{time(s.ends_at)}}</span><h3>{{s.title}}</h3><p>{{roomName(s.classroom)}}</p><span class="badge" :class="s.mode==='Online'?'violet':'peach'">{{s.mode}} · {{s.status}}</span><p v-if="s.location"><Icon name="MapPin" :size="14"/> {{s.location}}</p><button class="text-button" @click="openRoom(rooms.find(r=>r.name===s.classroom))">View classroom <Icon name="ArrowRight" :size="15"/></button><button v-if="manager" class="text-button" @click="edit('session',rooms.find(r=>r.name===s.classroom),s)">Edit session</button></article><article v-for="task in datedTasks(pickedDate)" class="agenda-item"><span class="badge mint">My to-do · {{task.done?'Completed':'Planned'}}</span><h3>{{task.title}}</h3><button class="text-button" @click="navigate('study')">Open Study Room</button></article><div v-if="!selectedSessions.length&&!datedTasks(pickedDate).length" class="empty-state"><Icon name="CalendarCheck2"/><p>No sessions on this day.</p></div></aside></div></template>

        <template v-else-if="page==='payments'"><div class="page-heading"><div><div class="eyebrow">ONE LESS THING TO WORRY ABOUT</div><h1>{{t.payments}} <HelpTip label="About payment access" text="A verified payment unlocks eligible classrooms. Grace periods and authorised overrides can adjust access. A checkout return page alone is not proof of payment."/></h1><p>Clear installments. Simple payments. More time for learning.</p></div><button v-if="manager" class="button subtle" @click="exportReport"><Icon name="Download" :size="17"/>Export loaded invoices</button></div><div class="payment-summary"><div class="panel"><span class="stat-icon mint"><Icon name="CheckCheck"/></span><p>Total settled</p><h2>{{lkr(stats.paid_total)}}</h2></div><div class="panel"><span class="stat-icon violet"><Icon name="Wallet"/></span><p>Outstanding balance</p><h2>{{lkr(stats.outstanding_total)}}</h2></div><div class="panel payment-note"><Icon name="ShieldCheck" :size="32"/><h3>Your learning stays connected.</h3><p>Classroom access updates automatically after a verified payment. Need a little more time? Contact your institute.</p></div></div><section class="panel"><div class="section-heading"><h2>Payment history</h2><div class="tabs"><button v-for="f in ['All','Paid','Unpaid','Overdue']" :class="{selected:paymentFilter===f}" @click="paymentFilter=f">{{f}}</button></div></div><div class="table-wrap"><table><thead><tr><th>Classroom / invoice</th><th>Installment</th><th>Due date</th><th>Amount</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="i in visibleInvoices" :key="i.name"><td><strong>{{roomName(i.classroom)}}</strong><small>{{i.name}}</small></td><td>{{String(i.installment).padStart(2,'0')}}</td><td>{{dateLabel(i.due_date)}}</td><td>{{lkr(i.amount)}}</td><td><span class="badge" :class="i.status==='Paid'?'green':i.status==='Overdue'?'rose':'amber'">{{i.status}}</span></td><td><button v-if="i.status==='Paid'" class="text-button" @click="receipt(i)"><Icon name="Download" :size="15"/>Receipt</button><button v-else-if="!manager" class="button small primary" @click="edit('payment',null,i)">Pay now <Icon name="ArrowUpRight" :size="14"/></button></td></tr></tbody></table><div v-if="isDemo&&filteredInvoices.length" class="community-pager"><span>{{invoicePage*25+1}}–{{Math.min((invoicePage+1)*25,filteredInvoices.length)}} of {{filteredInvoices.length}} invoices</span><div class="inline"><button class="button subtle small" :disabled="!invoicePage" @click="invoicePage--">Previous</button><button class="button subtle small" :disabled="(invoicePage+1)*25>=filteredInvoices.length" @click="invoicePage++">Next</button></div></div><div v-if="!filteredInvoices.length" class="empty-state"><Icon name="Receipt"/><p>No invoices to show.</p></div></div></section></template>

        <template v-else-if="page==='news'"><div class="page-heading"><div><div class="eyebrow">GOOD THINGS ARE HAPPENING</div><h1>Keep Me Update</h1><p>Fresh news, new opportunities, and a little inspiration.</p></div><button v-if="manager" class="button primary" @click="edit('news')"><Icon name="Plus" :size="17"/>Publish an update</button></div><FollowUpdates :member="boot.member"/><div class="news-grid"><article v-for="item in news" :key="item.name" class="news-card"><div class="news-image"><img :src="item.images[newsIndex[item.name]||0]?.image" :alt="item.images[newsIndex[item.name]||0]?.alt" loading="lazy"><div v-if="item.images.length>1" class="carousel-controls"><button class="round-button" aria-label="Previous image" @click="changeNews(item,-1)"><Icon name="ChevronLeft" :size="17"/></button><span>{{(newsIndex[item.name]||0)+1}} / {{item.images.length}}</span><button class="round-button" aria-label="Next image" @click="changeNews(item,1)"><Icon name="ChevronRight" :size="17"/></button></div></div><div class="news-copy"><span class="eyebrow">CAMPUS NOTICEBOARD · {{dateLabel(item.starts_on)}}</span><h2>{{item.headline}}</h2><p>{{item.description}}</p><a v-if="safeLink(item.cta_url)" class="text-button" :href="safeLink(item.cta_url)" target="_blank" rel="noopener noreferrer">{{item.cta_label||'Learn more'}}<Icon name="ArrowUpRight" :size="16"/></a><button v-else-if="isDemo&&item.cta_label" class="text-button" @click="navigate('classrooms')">{{item.cta_label}}<Icon name="ArrowRight" :size="16"/></button><small>Visible until {{dateLabel(item.ends_on)}} · Auto-deleted 30 days after publication</small></div></article></div><div v-if="!news.length" class="empty-state"><Icon name="Newspaper"/><h3>A quiet noticeboard, for now.</h3><p>Your institute’s news will appear here.</p></div></template>

        <template v-else-if="page==='notifications'"><div class="page-heading"><div><div class="eyebrow">ALWAYS IN THE LOOP</div><h1>{{t.notifications}}</h1><p>Your classes, materials and payments, all caught up.</p></div><button class="button subtle" @click="navigate('settings')">Notification preferences</button></div><section class="panel"><article v-for="n in notices" class="notice-item"><span class="stat-icon violet"><Icon :name="n.body.includes('ayment')?'Receipt':'Bell'"/></span><div><h3>{{n.body}}</h3><p>{{dateLabel(n.creation)}} · {{n.channel||'WhatsApp'}} <span class="badge" :class="n.status==='Accepted'?'green':'amber'">{{n.status}}</span></p></div></article><div v-if="!notices.length" class="empty-state"><Icon name="Bell"/><p>You’re all caught up.</p></div><p class="muted-text">Accepted means the message was handed to WhatsApp or the email queue; it does not confirm delivery. Preview notifications are simulated.</p></section></template>

        <Community v-else-if="isDemo&&manager&&['people','teachers'].includes(page)&&insightsData" :key="page" :data="insightsData" :teachers="page==='teachers'" @create="admin?edit('member'):notify('Ask your institute administrator to register a new student.')"/>
        <MarketingStudio v-else-if="isDemo&&manager&&page==='marketing'&&insightsData" :data="insightsData" @refresh="refresh" @notify="notify"/>
        <Competition v-else-if="isDemo&&page==='competition'&&insightsData" :key="persona" :data="insightsData" :member="boot.member"/>
        <template v-else-if="page==='people'&&admin"><div class="page-heading"><div><div class="eyebrow">THE PEOPLE WHO MAKE IT POSSIBLE</div><h1>Your campus community</h1><p>One institute. Individual journeys.</p></div><button class="button primary" @click="edit('member')"><Icon name="UserPlus" :size="17"/>Add a member</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Institute ID</th><th>Role</th><th>Email</th><th>Status</th></tr></thead><tbody><tr v-for="m in members"><td><div class="inline"><span class="teacher-avatar">{{m.full_name.slice(0,1)}}</span><strong>{{m.full_name}}</strong></div></td><td>{{m.name}}</td><td><span class="badge violet">{{m.role}}</span></td><td>{{m.user||'—'}}</td><td><button class="badge" :class="m.active?'green':'rose'" @click="toggleMember(m)" :aria-label="(m.active?'Deactivate ':'Activate ')+m.full_name">{{m.active?'Active':'Inactive'}} · Change</button></td></tr></tbody></table></div></section></template>

        <template v-else-if="page==='hub'"><div class="page-heading"><div><span class="eyebrow">EVERYTHING IN ITS LITTLE PLACE</span><h1>{{manager?'Your teaching desk.':'Your learning desk.'}}</h1><p>Courses, practice and milestones. Together, without the clutter.</p></div></div><div class="learning-grid"><button v-for="item in hubItems" class="panel learning-card" @click="navigate(item.id)"><span class="stat-icon violet"><Icon :name="item.icon" :size="24"/></span><h2>{{item.label}}</h2><p>{{item.description}}</p><span class="text-button">Open <Icon name="ArrowRight" :size="15"/></span></button></div></template><StudySpace v-else-if="page==='study'&&boot.member.role==='Student'" :key="boot.member.name" :member="boot.member" @notify="notify"  :standalone="true" @navigate="navigate"/><VideoCourses v-else-if="isDemo&&page==='videos'" :key="persona" :member="boot.member" :teachers="teacherOptions" @notify="notify" @refresh="refresh" @payments="navigate('payments')" @quizzes="navigate('quizzes')"/><template v-else-if="page==='learning'"><div class="page-heading"><div><div class="eyebrow">KEEP YOUR CURIOSITY GOING</div><h1>{{t.learning}}</h1><p>Your familiar Frappe Learning tools, connected to your institute.</p></div></div><div class="learning-grid"><a v-for="tool in [{name:'Courses',icon:'BookOpen',path:'courses',body:'Lessons, learning records and course progress.'},{name:'Quizzes',icon:'ClipboardCheck',path:'quizzes',body:'Practice what you know and check your understanding.'},{name:'Assignments',icon:'NotebookPen',path:'assignments',body:'Your work, submissions and teacher feedback.'},{name:'Certificates',icon:'Award',path:'user/'+encodeURIComponent(boot.username||boot.member.user||'me')+'/certificates',body:'Every milestone deserves a little celebration.'}]" :href="isDemo?'#':(boot.lms_base||'/lms')+'/'+tool.path" class="panel learning-card" @click="isDemo&&( $event.preventDefault(),notify('This opens the existing Frappe LMS '+tool.name.toLowerCase()+' on your installed site.'))"><span class="stat-icon violet"><Icon :name="tool.icon" :size="25"/></span><h2>{{tool.name}}</h2><p>{{tool.body}}</p><span class="text-button">Open {{tool.name.toLowerCase()}} <Icon name="ArrowUpRight" :size="17"/></span></a></div><p class="muted-text">Classroom payments govern this portal’s materials and sessions. Native course enrollment and access remain managed by Frappe LMS.</p></template>

        <template v-else-if="page==='settings'"><div class="page-heading"><div><div class="eyebrow">MAKE YOURSELF AT HOME</div><h1>{{t.settings}}</h1><p>A learning space that feels like yours.</p></div></div><div class="settings-grid"><section class="panel"><div class="section-heading"><h2>Your profile</h2><span class="badge violet">{{boot.member.role}}</span></div><div class="profile-summary"><span class="avatar big">{{boot.member.full_name.slice(0,1)}}</span><div><h3>{{boot.member.full_name}}</h3><p>{{boot.member.name||'Site administrator'}}</p></div></div><form @submit.prevent="savePreferences"><label>WhatsApp number<input name="phone" type="tel" :value="boot.member.phone" placeholder="+94771234567"></label><label class="checkbox-label"><input name="opted_in" type="checkbox" :checked="boot.member.whatsapp_opt_in">Send me class and payment updates on WhatsApp</label><p class="field-help">You can change this preference anytime. Your selected interface language is used for notifications where an approved template is available.</p><button class="button primary">Save preferences</button></form><a v-if="!isDemo" class="text-button logout" href="/api/method/logout">Sign out <Icon name="LogOut" :size="16"/></a></section><section class="panel"><div class="section-heading"><h2>{{boot.institute.title}}</h2><Icon name="Building2"/></div><p>Institute code <strong>{{boot.institute.code}}</strong></p><div class="id-examples"><span>Student ID <code>ST-{{boot.institute.code}}-00001</code></span><span>Teacher ID <code>TC-{{boot.institute.code}}-0001</code></span></div><p>Your institute name, logo and identity travel with your learning space.</p><button v-if="admin" class="button primary" @click="edit('branding')"><Icon name="Palette" :size="17"/>Customise branding</button><div v-if="manager" class="integration-block"><h3>YouTube Live</h3><p>Connect your own channel to schedule classroom broadcasts.</p><button class="button subtle" @click="youtube('connect')"><Icon name="Youtube" :size="17"/>Connect YouTube</button></div></section><section v-if="isDemo" class="panel"><h3>Preview workspace</h3><p>This preview uses sample data in your browser. Live integrations require your Frappe site and provider credentials.</p><button class="button subtle" @click="resetDemo();refresh();notify('Preview reset to the original sample data.')">Reset sample data</button></section></div></template>
        <div v-if="!isDemo&&!noMore[page]&&(({classrooms:rooms.length,people:members.length,payments:invoices.length,news:news.length,notifications:notices.length})[page]||0)>=({classrooms:24,people:50,payments:50,news:24,notifications:50})[page]" class="pagination"><button class="button subtle" @click="loadMore">Load more <Icon name="ChevronDown" :size="16"/></button></div>
        <AccountControls v-if="page==='settings'&&role!=='PlatformAdmin'" :member="boot.member" :rooms="rooms" :institute="boot.institute" @refresh="refresh" @notify="notify"/>
        <StudentAppearance v-if="page==='settings'&&boot.member.role==='Student'" :key="boot.member.name+appearance.mode" :member="boot.member" @notify="notify" @study="navigate('study')"/><ContactSettings v-if="page==='settings'&&boot.member.name&&boot.member.role!=='PlatformAdmin'" :key="boot.member.name" :member="boot.member" @notify="notify"/>
        <footer class="main-footer"><span>Made for brighter tomorrows.</span><span>{{boot.institute.title}} <span>·</span> Powered by sisu</span></footer>
      </main>
    </div>

    <div v-if="toast" class="toast" role="status"><Icon name="CircleCheck" :size="19"/>{{toast}}<button class="icon-button small" aria-label="Dismiss notification" @click="toast=''"><Icon name="X" :size="15"/></button></div>
    <div v-if="modal" class="modal-backdrop" @click.self="closeDialog"><section class="modal" :class="{wide:modal==='room'}" role="dialog" aria-modal="true" aria-labelledby="modal-title" @keydown="trapFocus">
      <button class="modal-close icon-button" aria-label="Close dialog" @click="closeDialog"><Icon name="X"/></button>
      <template v-if="modal==='room'&&selected"><ClassProfileHeader expanded :room="{...rooms.find(r=>r.name===selected.room.name),...selected.room}"/><div v-if="selected.room.exam_date||selected.room.motivation" class="class-profile-exam inline wrap"><span v-if="selected.room.exam_date" class="badge violet"><Icon name="Hourglass" :size="14"/>{{remaining(selected.room.exam_date)}} days to {{selected.room.exam_type||'exam'}}</span><strong>{{selected.room.motivation}}</strong></div><div class="detail-content"><div v-if="manager" class="detail-actions"><button class="button subtle small classroom-danger" v-if="selected.room.permissions?.delete" @click="confirmDelete"><Icon name="Trash2" :size="15"/>Delete classroom</button><button v-if="selected.room.permissions?.edit" class="button subtle small" @click="edit('classroom',selected.room)"><Icon name="Pencil" :size="15"/>Edit classroom</button><button class="button primary small" @click="edit('session',selected.room)"><Icon name="Plus" :size="15"/>Schedule session</button><button class="button subtle small" @click="edit('material',selected.room)">Add material</button><button class="button subtle small" @click="edit('announcement',selected.room)">Announce</button><button v-if="false" class="button subtle small" @click="edit('enroll',selected.room)">Enroll student</button></div><p v-if="manager" class="field-help">{{selected.room.owner_type==='Teacher'?'Independent classroom · fees paid to its teacher':'Institute classroom · all class fees paid to the institute'}} · {{selected.room.teacher_access||'Teaching only'}}</p><button v-if="role==='Teacher'&&selected.room.owner_type==='Institute'" class="text-button" @click="leaveAssignment">Leave this class assignment</button><div v-if="!selected.access.allowed" class="locked-state"><span class="stat-icon peach"><Icon name="LockKeyhole" :size="28"/></span><h3>A little step before you start.</h3><p>{{selected.access.reason}}. Settle your installment to unlock this classroom, or ask your institute about a grace period.</p><button class="button primary" @click="closeDialog();navigate('payments')">View my payments <Icon name="ArrowRight" :size="17"/></button></div><template v-else><div class="tabs detail-tabs"><button v-for="tab in ['Sessions','Materials','Noticeboard','Feedback',...(manager?['Students']:[])]" :class="{selected:detailTab===tab}" @click="detailTab=tab">{{tab}}</button></div><template v-if="detailTab==='Sessions'"><article v-for="s in selected.sessions" class="detail-session"><div class="session-date"><strong>{{new Date(s.starts_at.slice(0,10)+'T12:00:00').getDate()}}</strong><span>{{new Date(s.starts_at.slice(0,10)+'T12:00:00').toLocaleDateString('en',{month:'short'})}}</span></div><div class="grow"><span class="badge" :class="s.status==='Completed'?'green':'violet'">{{s.mode}} · {{s.status}}</span><h3>{{s.title}}</h3><p>{{time(s.starts_at)}} – {{time(s.ends_at)}} · {{s.location||'Your online classroom'}}</p><p v-if="s.description">{{s.description}}</p><button v-if="s.youtube_id" class="text-button" @click="activeVideo=s.youtube_id"><Icon name="Play" :size="15"/>{{s.status==='Completed'?'Watch recording':'Open live class'}}</button><a v-else-if="safeLink(s.meeting_url)" :href="safeLink(s.meeting_url)" class="button primary small" target="_blank" rel="noopener noreferrer">Join {{s.meeting_provider}} ↗</a><button v-else-if="manager&&s.mode==='Online'&&(!s.meeting_provider||s.meeting_provider==='YouTube')" class="text-button" @click="closeDialog();navigate('live')">Create YouTube Live</button><small v-else-if="s.mode==='Online'">Your teacher will add the live link before class.</small><LessonQuiz v-if="isDemo&&!manager&&s.status==='Completed'" :key="s.name" :session="s"/><div v-if="manager&&s.youtube_id&&s.mode==='Online'" class="inline wrap"><button class="text-button" @click="youtube('sync_broadcast',s)">Sync YouTube schedule</button><button class="text-button" @click="youtube('transition_broadcast',s,s.status==='Live'?'complete':'live')">{{s.status==='Live'?'End broadcast':'Start broadcast'}}</button><a href="https://studio.youtube.com/" target="_blank" rel="noopener noreferrer" class="text-button">Open Studio</a></div><p v-if="s.youtube_privacy==='private'" class="field-help">Private videos require a separately invited Google account; LMS access alone does not grant YouTube access.</p></div><button v-if="manager" class="icon-button" aria-label="Edit session" @click="edit('session',selected.room,s)"><Icon name="Pencil" :size="17"/></button></article><p v-if="!selected.sessions.length" class="empty-mini">Your next sessions will appear here.</p></template><template v-if="detailTab==='Materials'"><template v-for="m in selected.materials" :key="m.name"><MaterialViewer v-if="m.file_id" :material="m" :member="boot.member"/><article v-else class="material-item"><span class="stat-icon violet"><Icon :name="m.kind==='Recording'?'Video':'FileText'"/></span><div class="grow"><h3>{{m.title}}</h3><p>{{m.description||m.kind}}</p></div><button v-if="m.youtube_id" class="button subtle small" @click="activeVideo=m.youtube_id">Watch <Icon name="Play" :size="14"/></button><a v-else-if="safeLink(m.url)" :href="safeLink(m.url)" target="_blank" rel="noopener noreferrer" class="button subtle small">Open <Icon name="ArrowUpRight" :size="14"/></a></article></template><p v-if="!selected.materials.length" class="empty-mini">No materials yet. Your teacher’s resources will appear here.</p></template><template v-if="detailTab==='Noticeboard'"><article v-for="a in selected.announcements" class="announcement"><span class="stat-icon peach"><Icon name="Megaphone"/></span><h3>{{a.headline}}</h3><p>{{a.body}}</p></article><p v-if="!selected.announcements.length" class="empty-mini">No announcements yet.</p></template><template v-if="detailTab==='Feedback'"><p class="field-help">Share feedback after your session. Teachers control comments for each classroom and session.</p><article v-for="f in selected.feedback" class="feedback-item"><span class="teacher-avatar">{{f.student===boot.member.name?'A':'S'}}</span><div><strong>{{f.student===boot.member.name?'You':f.student}}</strong><p>{{f.body}}</p></div></article><form v-if="!manager" @submit.prevent="sendComment"><label>Completed session<select v-model="form.feedback_session" required><option disabled :value="undefined">Choose a session</option><option v-for="s in selected.sessions.filter(s=>Date.parse(s.ends_at.replace(' ','T')+'+05:30')<=Date.now() && s.status!=='Cancelled' && (s.comments==='Enabled'||(s.comments==='Inherit'&&selected.room.comments_enabled)))" :value="s.name">{{s.title}}</option></select></label><label>Your feedback<textarea v-model="comment" maxlength="1000" required placeholder="What helped you learn today?"></textarea></label><button class="button primary">Post feedback</button></form></template><template v-if="detailTab==='Students'"><article v-for="e in enrollments" class="material-item"><span class="teacher-avatar">S</span><div class="grow"><h3>{{e.student}}</h3><p>{{e.access_override}} access <span v-if="e.grace_until">· Grace until {{dateLabel(e.grace_until)}}</span></p></div><button v-if="admin||selected.room.allow_teacher_access_override" class="button subtle small" @click="edit('access',selected.room,e)">Manage access</button></article><p v-if="!enrollments.length" class="empty-mini">No enrolled students yet.</p></template><div v-if="!isDemo&&!detailEnd&&['sessions','materials','feedback','announcements'].some(k=>selected[k].length>=50)" class="pagination"><button class="button subtle" @click="moreDetail">Load older classroom content</button></div><div v-if="activeVideo" class="video-frame"><iframe :src="'https://www.youtube-nocookie.com/embed/'+encodeURIComponent(activeVideo)" title="Classroom video" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe><p>YouTube privacy and channel restrictions still apply. Unlisted links can be shared outside the classroom.</p></div></template></div></template>
      <template v-else-if="modal==='video'&&isDemo"><div class="video-modal"><span class="eyebrow">SISU LANKA · YOUTUBE PLAYER DEMONSTRATION</span><h2 id="modal-title">Step inside the classroom.</h2><iframe :src="'https://www.youtube.com/embed/YSul9yrAvN4?rel=0&origin='+encodeURIComponent(locationOrigin)" title="Teacher Teaching the Students Inside a Classroom — supplied YouTube example" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe><p>Teacher Teaching the Students Inside a Classroom · Your supplied stock video is a playback example, not a subject lesson. Video streams from YouTube; only its ID is stored in the LMS.</p><a href="https://youtu.be/YSul9yrAvN4" target="_blank" rel="noopener noreferrer" class="text-button">Open on YouTube if playback is restricted <Icon name="ArrowUpRight" :size="15"/></a></div></template>
      <template v-else-if="modal==='delete-classroom'&&selected"><form class="form-content" @submit.prevent="removeClassroom"><h2 id="modal-title">Delete this classroom?</h2><p><strong>{{selected.room.title}}</strong> will be removed from active classrooms and schedules. Students will lose classroom access. Materials, enrollments, results and payment history are kept.</p><p>You can restore it from <strong>Deleted classrooms</strong>. This does not refund payments or cancel external YouTube broadcasts.</p><label>Type the classroom title to confirm<input v-model="deleteName" required autocomplete="off"></label><p v-if="error" class="error" role="alert">{{error}}</p><div class="inline wrap"><button type="button" class="button subtle" :disabled="busy" @click="openDialog('room')">Keep classroom</button><button class="button primary classroom-danger-solid" :disabled="busy||deleteName!==selected.room.title">{{busy?'Deleting…':'Delete classroom'}}</button></div></form></template>
      <template v-else-if="modal==='deleted-classrooms'"><div class="form-content"><h2 id="modal-title">Deleted classrooms</h2><p>Restore a classroom to make its saved schedule and access rules available again. Related records are kept.</p><p v-if="error" class="error" role="alert">{{error}}</p><article v-for="room in deletedRooms" :key="room.name" class="material-item"><div class="grow"><h3>{{room.title}}</h3><p>{{room.subject}} · {{room.teacher_name}}</p></div><button class="button subtle small" :disabled="busy" @click="restoreClassroom(room)">Restore classroom</button></article><p v-if="!deletedRooms.length">No deleted classrooms on this page.</p><div class="inline wrap"><button class="button subtle" :disabled="busy||!deletedPage" @click="showDeleted(deletedPage-1)">Previous</button><button class="button subtle" :disabled="busy||deletedRooms.length<24" @click="showDeleted(deletedPage+1)">Next</button></div></div></template>
      <template v-else-if="modal==='support'"><div class="form-content"><span class="stat-icon mint"><Icon name="HeartHandshake" :size="28"/></span><h2 id="modal-title">A little help is always here.</h2><p>For classroom access, fees or timetable changes, contact your teacher or {{boot.institute.title}}’s office.</p><p>Your student reference: <strong>{{boot.member.name}}</strong></p><button class="button primary" @click="closeDialog();navigate('classrooms')">Find my classroom</button></div></template>
      <form v-else class="form-content" @submit.prevent="submit"><span class="eyebrow">YOUR SPACE, YOUR WAY</span><h2 id="modal-title">{{({classroom:form.name?'Make this classroom yours':'Create a classroom',session:'Plan your next class',material:'Share a learning resource',announcement:'Keep your class in the loop',news:'Something worth sharing',member:'Welcome someone new',enroll:'Start a learning journey',access:'Classroom access',payment:'A step closer to learning',branding:'Make it feel like your institute'})[modal]}}</h2><p v-if="error" class="error" role="alert">{{error}}</p>
        <template v-if="modal==='classroom'"><label>Classroom title <span>English · සිංහල · தமிழ்</span><input v-model="form.title" required maxlength="120" placeholder="නිමල් සර්ගේ ගණන් පන්තිය"></label><div class="form-row"><label>Subject<input v-model="form.subject" required maxlength="60" placeholder="Combined Mathematics"></label><label>Teacher<select v-model="form.teacher" required :disabled="!admin"><option v-for="m in teacherOptions" :value="m.name">{{m.full_name}}</option></select></label></div><div class="form-row"><label>Billing model<select v-model="form.billing_type" :disabled="!!form.programme"><option>Monthly</option><option>One-time</option><option v-if="form.programme">Programme module</option></select></label><label v-if="admin">Teacher permission<select v-model="form.teacher_access"><option>Teaching only</option><option>Full control</option></select></label><label>Class fee type<select v-model="form.fee_mode"><option>Paid</option><option>Free</option></select></label><label>Public timetable<input v-model="form.schedule_label" maxlength="140" placeholder="Grade 6 · Sundays, 5:00 PM · Asia/Colombo"></label></div><p class="field-help">Free waives the teaching fee. Any assigned platform fee is shown separately at checkout.</p><label>Provider<select v-model="form.public_provider" :disabled="!admin&&!!form.name"><option value="">Choose a verified provider</option><option v-for="p in publishingOptions.filter(p=>admin?p.kind==='Institute':p.kind==='Teacher'||p.name===form.public_provider)" :value="p.name">{{p.display_name}} · {{p.kind}}</option></select></label><label class="checkbox-label"><input v-model="form.published" type="checkbox" :true-value="1" :false-value="0">Show this classroom on the provider’s public profile</label><p v-if="!publishingOptions.length" class="field-help">Save a draft now. After your provider profile is verified, return here to publish it for students.</p><label>Description<textarea v-model="form.description" maxlength="1500" placeholder="What makes this classroom special?"></textarea></label><div class="form-row"><label>Title style<select v-model="form.font"><option value="sans">Clear & modern · Noto Sans</option><option value="serif">Warm & classic · Noto Serif</option><option value="handwritten">Creative Sinhala · Gemunu Libre + Caveat</option></select></label><label>Tuition fee · LKR<input v-model.number="form.fee" type="number" min="0" step="0.01" :disabled="form.fee_mode==='Free'||!!form.programme"></label></div><p class="title-preview" :class="form.font">{{form.title||'Your classroom, your personality.'}}</p><p class="field-help">Creative Sinhala uses Gemunu Libre, a Unicode display typeface; English uses Caveat handwriting. Tamil and unsupported characters use readable Noto fallbacks.</p><div class="form-row"><label>Profile image<input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,'profile_image')"><img v-if="form.profile_image" class="upload-preview" :src="form.profile_image" alt="Profile preview"></label><label>Class banner · 16:9 · maximum 5 MB<input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,'cover_image')"><img v-if="form.cover_image" class="upload-preview" :src="form.cover_image" alt="Cover preview"></label></div><div class="form-row"><label>Exam type<input v-model="form.exam_type" list="exam-types" maxlength="120" placeholder="Select or type any exam"><datalist id="exam-types"><option v-for="exam in ['Mid-term exam','Year-end exam','Monthly exam','Semester exam','GCE O/L','GCE A/L','Grade 5 Scholarship','GCSE','IGCSE','IB Diploma','AP exam','University final','Professional certification','Entrance exam']">{{exam}}</option></datalist></label><label>Exam date<input v-model="form.exam_date" type="date"></label><label>Curriculum<input v-model="form.curriculum" maxlength="120" placeholder="Sri Lankan local syllabus"></label><label>Grade / level<input v-model="form.grade" maxlength="120" placeholder="Grade 6"></label><label>Teaching medium<input v-model="form.teaching_medium" maxlength="120" placeholder="Sinhala, English"></label><label>Motivation line <HelpTip text="Up to 30 visible characters, including Sinhala and Tamil. Combining marks are counted with their base character."/><span>{{graphemes(form.motivation)}} / 30</span><input v-model="form.motivation" placeholder="පුංචි පියවර, ලොකු හීන"></label></div><label class="checkbox-label"><input type="checkbox" v-model="form.comments_enabled" :true-value="1" :false-value="0">Allow comments after sessions</label><label v-if="admin" class="checkbox-label"><input type="checkbox" v-model="form.allow_teacher_access_override" :true-value="1" :false-value="0">Allow this teacher to manage unpaid student access</label></template>
        <template v-if="modal==='session'"><label>Classroom<select v-model="form.classroom" required :disabled="!!form.name"><option v-for="r in rooms" :value="r.name">{{r.title}}</option></select></label><label>Session title<input v-model="form.title" required maxlength="120" placeholder="Integration, one step at a time"></label><div class="form-row"><label>Starts · Sri Lanka time<input v-model="form.starts_at" type="datetime-local" required></label><label>Ends · Sri Lanka time<input v-model="form.ends_at" type="datetime-local" required></label></div><div class="form-row"><label>Class type<select v-model="form.mode"><option>Online</option><option>Physical</option></select></label><label>Status<select v-model="form.status"><option>Scheduled</option><option>Live</option><option>Completed</option><option>Cancelled</option></select></label></div><label>{{form.mode==='Physical'?'Venue / classroom':'Location note'}}<input v-model="form.location" maxlength="200" :required="form.mode==='Physical'" placeholder="Nugegoda · Hall 02"></label><label v-if="form.mode==='Online'">Live provider<select v-model="form.meeting_provider" @change="form.meeting_url='';form.youtube_id=''"><option>YouTube</option><option>Zoom</option><option>Google Meet</option></select></label><label v-if="form.mode==='Online'&&form.meeting_provider!=='YouTube'">{{form.meeting_provider}} meeting link<input v-model="form.meeting_url" type="url" placeholder="https://…"><span>Visible only inside an unlocked classroom. Use the provider’s waiting room and access settings.</span></label><label v-if="form.mode==='Online'&&form.meeting_provider==='YouTube'">YouTube video URL or ID <HelpTip text="Paste a public or unlisted YouTube video URL with embedding enabled. Private videos require an invited Google account. Adding a URL here does not change its YouTube privacy settings."/><span>Optional</span><input v-model="form.youtube_id" placeholder="https://www.youtube.com/watch?v=…"></label><label>Description<textarea v-model="form.description" maxlength="2000"></textarea></label><label>Session comments<select v-model="form.comments"><option value="Inherit">Use classroom setting</option><option value="Enabled">Enable after this session</option><option value="Disabled">Disable for this session</option></select></label><p class="form-note"><Icon name="MessageCircle" :size="17"/>Students who opted in will receive a WhatsApp update.</p></template>
        <template v-if="modal==='material'"><label>Title<input v-model="form.title" required maxlength="120"></label><label>Resource type<select v-model="form.kind"><option>Document</option><option>Recording</option><option>Link</option></select></label><MaterialUpload v-if="form.kind==='Document'" :form="form" :member="boot.member" @busy="busy=$event"/><label v-else>{{form.kind==='Recording'?'YouTube URL or video ID':'Resource HTTPS URL'}}<HelpTip v-if="form.kind==='Recording'" text="Public and unlisted YouTube videos can play here when embedding is allowed. Private videos require the owner's Google invitation."/><input v-model="form.url" required :type="form.kind==='Recording'?'text':'url'" placeholder="https://…"></label><label>Description<textarea v-model="form.description" maxlength="1000"></textarea></label><p v-if="form.kind==='Link'" class="field-help">External links follow the external provider's access and download settings.</p></template>
        <template v-if="modal==='announcement'"><label>Headline<input v-model="form.headline" required maxlength="80"></label><label>Announcement<textarea v-model="form.body" required maxlength="2000"></textarea></label></template>
        <template v-if="modal==='news'"><label>Headline <span>{{graphemes(form.headline)}} / 80</span><input v-model="form.headline" required></label><label>Short description <span>{{graphemes(form.description)}} / 240</span><textarea v-model="form.description" required></textarea></label><div class="form-row"><label>Show from<input v-model="form.starts_on" type="date" required></label><label>Show until<input v-model="form.ends_on" type="date" required :min="form.starts_on"></label></div><p class="field-help">News and marketing posts are automatically removed 30 days after publication, even if their display end date is later.</p><label>Images <span>{{form.images.length}} / 5 · up to 2 MB each</span><input type="file" accept="image/png,image/jpeg,image/webp" multiple @change="upload($event,'images')"></label><div class="upload-thumbnails"><div v-for="(image,i) in form.images"><img :src="image.image" :alt="image.alt"><button type="button" @click="form.images.splice(i,1)" aria-label="Remove image"><Icon name="X" :size="13"/></button></div></div><div class="form-row"><label>Button label <span>Optional</span><input v-model="form.cta_label" maxlength="24"></label><label>Button link <span>HTTPS</span><input v-model="form.cta_url" type="url" placeholder="https://…"></label></div></template>
        <template v-if="modal==='member'"><label>Full name<input v-model="form.full_name" required maxlength="100"></label><label>Email<input v-model="form.user" type="email" required></label><div class="form-row"><label>Role<select v-model="form.role"><option>Teacher</option><option>Admin</option></select></label><label>Language<select v-model="form.language"><option value="en">English</option><option value="si">සිංහල</option><option value="ta">தமிழ்</option></select></label></div><label>Phone<input v-model="form.phone" type="tel" placeholder="+94771234567"></label><template v-if="isDemo&&form.role==='Student'"><div class="form-row"><label>Programme<select v-model="form.category"><option>Grade 5 Scholarship</option><option>O/L</option><option>A/L</option><option>University</option><option>Online Courses</option></select></label><label>Teaching medium<select v-model="form.medium"><option>Sinhala</option><option>Tamil</option><option>English</option></select></label></div><div class="form-row"><label>Grade / year<input v-model="form.grade" maxlength="20"></label><label>Stream<input v-model="form.stream" maxlength="60"></label></div><label>School / institution<input v-model="form.school" maxlength="120"></label><div class="form-row"><label>District<input v-model="form.district" maxlength="40"></label><label>Guardian name · if applicable<input v-model="form.guardian" maxlength="100"></label></div><p class="field-help">Demo registration saves a synthetic membership in this browser. It does not create a Frappe login or send an invitation.</p></template><p class="form-note"><Icon name="IdCard" :size="19"/>An institute ID is generated automatically. Members set their password through Frappe’s password reset flow.</p></template>
        <template v-if="modal==='enroll'"><label>Student<input v-model="form.student" required list="student-options" placeholder="ST-BC-00001"><datalist id="student-options"><option v-for="m in members.filter(m=>m.role==='Student')" :value="m.name">{{m.full_name}}</option></datalist></label><p>Classroom fee: <strong>{{lkr(rooms.find(r=>r.name===form.classroom)?.fee)}}</strong></p><div v-for="(i,index) in form.installments" class="form-row"><label>Installment {{index+1}} (LKR)<input v-model.number="i.amount" type="number" min="0.01" step="0.01" required></label><label>Due date<input v-model="i.due_date" type="date" required></label><button v-if="form.installments.length>1" type="button" class="icon-button" aria-label="Remove installment" @click="form.installments.splice(index,1)"><Icon name="X" :size="16"/></button></div><button type="button" class="text-button" @click="form.installments.push({amount:0,due_date:dayKey()})">+ Add installment</button></template>
        <template v-if="modal==='access'"><label>Access rule<select v-model="form.override"><option>Automatic</option><option>Open</option><option>Closed</option></select></label><label>Grace period ends <HelpTip text="Automatic access remains open through this date. A manual Closed override still takes precedence."/><span>Optional</span><input v-model="form.grace_until" type="date"></label><label>Reason for this change<textarea v-model="form.reason" required maxlength="500"></textarea></label><p class="field-help">Open and Closed override payment rules. Automatic follows payment and grace-period rules. Every change is recorded in the access audit.</p></template>
        <template v-if="modal==='payment'"><p>Invoice <strong>{{form.invoice}}</strong> · {{lkr(invoices.find(i=>i.name===form.invoice)?.amount)}}</p><div v-if="isDemo" class="form-note">Preview only. No real payment will be taken.</div><div class="form-row"><label>First name<input v-model="form.first_name" required></label><label>Last name<input v-model="form.last_name" required></label></div><label>Phone<input v-model="form.phone" type="tel" required></label><label>Billing address<input v-model="form.address" required></label><label>City<input v-model="form.city" required></label><p class="field-help">You’ll continue to {{paymentProvider}} to pay securely. Access updates after the payment is verified by the server.</p><button v-if="isDemo" type="button" class="button primary" @click="demoPay">Simulate successful payment</button></template>
        <template v-if="modal==='branding'"><label>Institute name<input v-model="form.title" required maxlength="100"></label><label>Institute code<input :value="form.code" disabled></label><label>Brand colour<input v-model="form.accent" type="color"></label><label>Institute logo<input type="file" accept="image/png,image/jpeg,image/webp" @change="upload($event,'logo')"><img v-if="form.logo" :src="form.logo" class="upload-preview" alt="Institute logo preview"></label></template>
        <div class="form-footer"><button type="button" class="button subtle" @click="closeDialog">Cancel</button><button v-if="!(modal==='payment'&&isDemo)" class="button primary" :disabled="busy">{{busy?'Saving…':modal==='payment'?'Continue to '+paymentProvider:modal==='news'?'Publish update':'Save changes'}}<Icon name="ArrowRight" :size="16"/></button></div>
      </form>
    </section></div>
    <SoulCompanion v-if="boot" :key="boot.member.name" :member="boot.member" :page="page" :language="lang" :event="toast" :suspended="!!modal||tourOpen" @navigate="navigate" @tour="tourOpen=true"/>
    <ProductTour v-if="tourOpen" :role="role" :demo="isDemo" @close="tourOpen=false" @navigate="navigate"/>
  </div>
</template>

<style>.hub-subnav{margin-bottom:20px}.coming-soon-strip{margin-top:25px;padding:25px}.coming-soon-strip p{font-size:12px;margin:14px 0}.learning-grid>button{text-align:left}.app-shell[data-student-theme=dark] .learning-card{color:var(--student-ink)}@media(max-width:700px){.signup-preview-button{font-size:10px;padding:7px}.tour-trigger{display:none}}@media(max-width:430px){.top-actions{gap:6px}.top-actions .profile-button{display:none}}</style>

<style>.button.classroom-danger{color:#a34661;background:#fbeef2}.button.classroom-danger-solid{background:#a34661;color:white}</style>

<style>.class-profile-exam{padding:0 32px 20px}.all-rooms .room-body>.inline.spread{margin:12px 0}.modal:has(.class-profile-header.is-expanded){max-width:1040px}</style>
